// Generates platform CSS from src/index.ts. Run with `bun run tokens` from the repo root.
import { join } from 'node:path';
import { palette, radius } from '../src/index';

const root = join(import.meta.dir, '..', '..', '..');
const header =
  '/* GENERATED by packages/tokens/scripts/build.ts. Edit packages/tokens/src/index.ts instead. */\n';
const vars = (mode: keyof typeof palette, wrap: (v: string) => string) =>
  Object.entries(palette[mode])
    .map(([k, v]) => `  --${k}: ${wrap(v)};`)
    .join('\n');

// Web: Tailwind v4 + shadcn/ui
const names = Object.keys(palette.light);
const web = `${header}
:root {
${vars('light', (v) => `hsl(${v})`)}
  --radius: ${radius};
}

.dark {
${vars('dark', (v) => `hsl(${v})`)}
}

@theme inline {
${names.map((k) => `  --color-${k}: var(--${k});`).join('\n')}
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}
`;

// Mobile: NativeWind v4 (Tailwind v3) + React Native Reusables
const native = `${header}
@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
${vars('light', (v) => v)
  .replaceAll('\n  ', '\n    ')
  .replace(/^ {2}/, '    ')}
    --radius: ${radius};
  }

  .dark:root {
${vars('dark', (v) => v)
  .replaceAll('\n  ', '\n    ')
  .replace(/^ {2}/, '    ')}
  }
}
`;

await Bun.write(join(root, 'packages/tokens/src/theme.css'), web);
await Bun.write(join(root, 'apps/mobile/global.css'), native);
console.log('tokens: wrote packages/tokens/src/theme.css and apps/mobile/global.css');
